-- Default-off foundation. The live Edge handler still uses its original
-- claim path. An opt-in server may call this single service-role RPC instead
-- of inserting a log and then calling begin_chat_v3_conversation_turn: denied
-- begins never leave an in_progress log, and a successful claim/lease/ledger
-- is one PostgreSQL transaction. p_log_id is generated by the Edge server
-- once per attempt, never supplied by the browser; retry that exact ID only
-- in the same serialized Edge attempt after an ambiguous RPC response.
BEGIN;

CREATE FUNCTION public.claim_and_begin_chat_v3_conversation_turn(
  p_token_digest text,
  p_log_id uuid,
  p_expected_version bigint,
  p_session_id text,
  p_message_id text,
  p_user_query text,
  p_steps jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
  v_conversation public.chat_v3_conversations%ROWTYPE;
  v_turn public.chat_v3_conversation_turns%ROWTYPE;
  v_log record;
  v_inserted_id uuid;
  v_now timestamptz;
  v_fence bigint;
BEGIN
  IF p_token_digest IS NULL OR p_token_digest !~ '^[0-9a-f]{64}$' OR
    p_log_id IS NULL OR p_expected_version IS NULL OR
    p_expected_version < 0 OR p_expected_version >= 1000000000 OR
    p_session_id IS NULL OR length(p_session_id) NOT BETWEEN 1 AND 128 OR
    p_session_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR
    p_message_id IS NULL OR NOT (
      p_message_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR
      p_message_id ~* '^msg_[0-9]{13}_[a-z0-9]{8}$'
    ) OR p_user_query IS NULL OR
    length(p_user_query) NOT BETWEEN 1 AND 2000 OR
    p_user_query <> btrim(p_user_query) OR
    p_steps IS NULL OR jsonb_typeof(p_steps) IS DISTINCT FROM 'array' OR
    jsonb_array_length(p_steps) > 128 OR
    octet_length(p_steps::text) > 32768 THEN
    RETURN jsonb_build_object('status', 'invalid_input');
  END IF;

  -- Lock order is conversation -> log -> ledger, matching finish and rotate.
  -- The bearer lookup, active topic, version and lease are all rechecked
  -- under this lock; a prior resolve() call is not an authority.
  SELECT * INTO v_conversation FROM public.chat_v3_conversations
  WHERE token_digest = p_token_digest FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('status', 'not_found'); END IF;
  v_now := clock_timestamp();
  IF v_conversation.status <> 'active' OR
    v_conversation.expires_at <= v_now OR
    (v_conversation.idle_expires_at <= v_now AND NOT (
      v_conversation.active_log_id IS NOT NULL AND
      coalesce(v_conversation.active_lease_until > v_now, false)
    )) THEN
    RETURN jsonb_build_object('status', 'inactive');
  END IF;

  SELECT id, chat_v3_topic_id, session_id, message_id, user_query,
      pipeline, error, response_events INTO v_log
  FROM public.chat_request_logs WHERE message_id = p_message_id FOR UPDATE;

  IF NOT FOUND THEN
    -- Denial happens before INSERT. This keeps the global message_id replay
    -- index free for a corrected retry after a stale/busy/inactive request.
    IF v_conversation.version <> p_expected_version THEN
      RETURN jsonb_build_object('status', 'stale_version',
        'version', v_conversation.version);
    END IF;
    IF v_conversation.turn_count >= 1000000000 OR
      v_conversation.fence >= 1000000000 THEN
      RETURN jsonb_build_object('status', 'turn_limit');
    END IF;
    IF v_conversation.active_log_id IS NOT NULL AND
      coalesce(v_conversation.active_lease_until > v_now, false) THEN
      RETURN jsonb_build_object('status', 'busy');
    END IF;

    -- The unique message_id index may race with a different topic, which is
    -- not locked by our conversation row. ON CONFLICT waits for its commit;
    -- classify the winner below without creating a second claim.
    INSERT INTO public.chat_request_logs
      (id, session_id, message_id, user_query, pipeline, branch, steps,
        response_events, final_products_count, final_response, total_ms,
        error, chat_v3_topic_id)
    VALUES
      (p_log_id, p_session_id, p_message_id, p_user_query, 'v3', 'v3_expert',
        p_steps, '[]'::jsonb, 0, NULL, 0, 'in_progress', v_conversation.id)
    ON CONFLICT DO NOTHING RETURNING id INTO v_inserted_id;
    IF v_inserted_id IS NULL THEN
      SELECT id, chat_v3_topic_id, session_id, message_id, user_query,
          pipeline, error, response_events INTO v_log
      FROM public.chat_request_logs WHERE message_id = p_message_id FOR UPDATE;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'log_id_conflict');
      END IF;
    ELSE
      -- A completed lease may be replaced. Its old turn is no longer an
      -- owner; terminalize its replay log in this same transaction so a
      -- reconnect does not poll an abandoned in_progress row indefinitely.
      IF v_conversation.active_log_id IS NOT NULL THEN
        UPDATE public.chat_v3_conversation_turns
        SET status = 'abandoned', finished_at = v_now
        WHERE log_id = v_conversation.active_log_id
          AND conversation_id = v_conversation.id
          AND status = 'in_progress';
        UPDATE public.chat_request_logs
        SET error = 'request_timeout', final_response = NULL,
          response_events = jsonb_build_array(
            jsonb_build_object('type', 'diagnostic', 'phase', 'complete',
              'log_id', v_conversation.active_log_id,
              'products_count', 0, 'error', 'request_timeout'),
            jsonb_build_object('type', 'done'))
        WHERE id = v_conversation.active_log_id
          AND chat_v3_topic_id = v_conversation.id
          AND error = 'in_progress';
      END IF;
      v_fence := v_conversation.fence + 1;
      UPDATE public.chat_v3_conversations
      SET fence = v_fence, turn_count = turn_count + 1,
        active_log_id = p_log_id,
        active_lease_until = v_now + interval '5 minutes',
        updated_at = v_now
      WHERE id = v_conversation.id;
      INSERT INTO public.chat_v3_conversation_turns
        (log_id, conversation_id, fence, expected_version, status, started_at)
      VALUES (p_log_id, v_conversation.id, v_fence,
        v_conversation.version, 'in_progress', v_now);
      RETURN jsonb_build_object('status', 'begun', 'recovered', false,
        'log_id', p_log_id, 'topic_id', v_conversation.id,
        'version', v_conversation.version, 'fence', v_fence,
        'state', v_conversation.state);
    END IF;
  END IF;

  -- Only the original topic, browser session and exact normalized request
  -- may replay a global message_id. A legacy NULL-bound row is a conflict.
  IF v_log.chat_v3_topic_id IS DISTINCT FROM v_conversation.id OR
    v_log.session_id IS DISTINCT FROM p_session_id OR
    v_log.user_query IS DISTINCT FROM p_user_query OR
    v_log.pipeline IS DISTINCT FROM 'v3' THEN
    RETURN jsonb_build_object('status', 'message_conflict');
  END IF;
  SELECT * INTO v_turn FROM public.chat_v3_conversation_turns
  WHERE log_id = v_log.id FOR UPDATE;
  IF NOT FOUND OR v_turn.conversation_id <> v_conversation.id THEN
    RETURN jsonb_build_object('status', 'invalid_claim');
  END IF;
  IF v_turn.status = 'finalized' AND v_log.error IS NULL THEN
    RETURN jsonb_build_object('status', 'finalized', 'replayed', true,
      'log_id', v_log.id, 'topic_id', v_conversation.id,
      'version', v_turn.result_version);
  END IF;
  IF v_turn.status = 'aborted' AND
    v_log.error IS NOT NULL AND v_log.error <> 'in_progress' THEN
    RETURN jsonb_build_object('status', 'failed', 'replayed', true,
      'log_id', v_log.id, 'topic_id', v_conversation.id,
      'version', v_turn.expected_version);
  END IF;
  IF v_turn.status = 'abandoned' AND
    v_log.error = 'request_timeout' AND
    v_log.response_events->-1 = '{"type":"done"}'::jsonb AND
    (v_log.response_events->-2)->>'type' = 'diagnostic' AND
    (v_log.response_events->-2)->>'phase' = 'complete' AND
    (v_log.response_events->-2)->>'log_id' = v_log.id::text AND
    (v_log.response_events->-2)->>'error' = v_log.error THEN
    -- A replacement turn fenced this expired owner and committed its
    -- terminal replay log. Return that failure, never run the old work again.
    RETURN jsonb_build_object('status', 'failed', 'replayed', true,
      'log_id', v_log.id, 'topic_id', v_conversation.id,
      'version', v_turn.expected_version);
  END IF;
  IF v_turn.status = 'in_progress' AND
    v_log.error = 'in_progress' AND
    v_conversation.active_log_id = v_log.id AND
    v_conversation.fence = v_turn.fence AND
    coalesce(v_conversation.active_lease_until > clock_timestamp(), false) THEN
    IF v_log.id = p_log_id AND
      v_turn.expected_version = p_expected_version THEN
      -- A retry with the *same server-generated log ID* recovers the result
      -- of an ambiguous RPC response in one serialized Edge attempt. A
      -- different ID is a competing request and must only wait for replay.
      RETURN jsonb_build_object('status', 'begun', 'recovered', true,
        'log_id', v_log.id, 'topic_id', v_conversation.id,
        'version', v_turn.expected_version, 'fence', v_turn.fence,
        'state', v_conversation.state);
    END IF;
    RETURN jsonb_build_object('status', 'turn_in_progress',
      'replayed', true, 'log_id', v_log.id,
      'topic_id', v_conversation.id);
  END IF;
  RETURN jsonb_build_object('status', 'stale_turn', 'log_id', v_log.id,
    'topic_id', v_conversation.id);
END;
$function$;

REVOKE EXECUTE ON FUNCTION public.claim_and_begin_chat_v3_conversation_turn(
  text, uuid, bigint, text, text, text, jsonb
) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_and_begin_chat_v3_conversation_turn(
  text, uuid, bigint, text, text, text, jsonb
) TO service_role;
COMMIT;
